    public static function pilot($d){return ($d['subject_code']??'')==='FR'&&(bool)preg_match('/^Jan(?:uary)?[ ,]*2026$/i',$d['exam_attempt']??'');}
    public static function extra($d){
        $v=$d['practice_structure']??array();$allowed=array('parent_stable_id','scenario_key','alternative','layout_profile','boundary_signature','quality_required');if(!is_array($v)||array_diff(array_keys($v),$allowed))return CAFCC_Repository::error('Invalid question structure.');foreach($v as $k=>$value){if($k==='quality_required'){if(!is_bool($value))return CAFCC_Repository::error('Invalid quality requirement.');continue;}if(!is_string($value)||strlen($value)>190||CAFCC_Bank_DB::private_reference($value))return CAFCC_Repository::error('Invalid structure field.');$v[$k]=sanitize_text_field($value);}if(!in_array($v['alternative']??'',array('','either','or'),true))return CAFCC_Repository::error('Identify Either/Or separately.');$d['practice_structure']=$v;
        $p=$d['source_provenance']??array();if(!is_array($p)||array_diff(array_keys($p),array('drive_file_id','answer_drive_file_id')))return CAFCC_Repository::error('Private provenance accepts file IDs only.');foreach($p as $id)if(!is_string($id)||!preg_match('/^[A-Za-z0-9_-]{10,120}$/D',$id))return CAFCC_Repository::error('Invalid private source file ID.');$d['source_provenance']=$p;
        $c=$d['quality_checks']??array();if(!is_array($c)||array_diff(array_keys($c),array('question_hash','answer_hash','scenario_hash','boundary','tables','figures','shared_facts','answer_complete','reviewer','reviewed_at','signature')))return CAFCC_Repository::error('Invalid source-comparison checklist.');foreach($c as $k=>$value){if($k==='reviewer'){if(!is_int($value)||$value<1)return CAFCC_Repository::error('Invalid comparison reviewer.');continue;}if(in_array($k,array('reviewed_at','signature'),true)){if(!is_string($value)||strlen($value)>100)return CAFCC_Repository::error('Invalid comparison signature.');continue;}if(str_ends_with($k,'_hash')){if(!is_string($value)||!preg_match('/^[a-f0-9]{64}$/D',$value))return CAFCC_Repository::error('Invalid comparison fingerprint.');}elseif(!is_bool($value))return CAFCC_Repository::error('Source-comparison decisions must be explicit.');}$d['quality_checks']=$c;return $d;
    }
    public static function scenario($source_hash,$key){global $wpdb;$t=CAFCC_Study::table('scenarios');return $wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE source_hash=%s AND scenario_key=%s",$source_hash,$key),ARRAY_A);}
    public static function scenario_batch($action,$v){if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if($action==='preview'){$rows=$v['scenarios']??null;if(!is_array($rows)||!array_is_list($rows)||!$rows||count($rows)>50)return CAFCC_Repository::error('Use 1–50 authorised common scenarios per batch.');$conflicts=array();foreach($rows as $row){if(!is_array($row)||!preg_match('/^[a-f0-9]{64}$/D',$row['source_hash']??'')||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$row['scenario_key']??'')||!is_string($row['body_html']??null)||strlen($row['body_html'])>500000||empty($row['rights_basis']))return CAFCC_Repository::error('Invalid authorised common facts.');$old=self::scenario($row['source_hash'],$row['scenario_key']);if($old&&$old['body_html']!==CAFCC_Practice::html($row['body_html']))$conflicts[]=$row['scenario_key'];}$token=wp_generate_uuid4();set_transient('cafcc_scenarios_'.$token,array('owner'=>get_current_user_id(),'rows'=>$rows),1800);return array('token'=>$token,'selected'=>count($rows),'conflicts'=>$conflicts,'can_apply'=>!$conflicts,'publication_status'=>'private');}$token=$v['token']??'';if(!is_string($token))return CAFCC_Repository::error('Invalid scenario preview.');$p=get_transient('cafcc_scenarios_'.$token);if(!$p||$p['owner']!==get_current_user_id())return CAFCC_Repository::error('Scenario preview expired or belongs to another owner.',409);return CAFCC_Academic::transaction(function()use($p,$token){$added=0;$retained=0;foreach($p['rows'] as $row){$old=self::scenario($row['source_hash'],$row['scenario_key']);if($old){if($old['body_html']!==CAFCC_Practice::html($row['body_html']))return CAFCC_Repository::error('Common facts changed after preview. Retain the newer correction.',409);$retained++;continue;}$saved=self::save_scenario($row);if(is_wp_error($saved))return $saved;$added++;}delete_transient('cafcc_scenarios_'.$token);return array('added_private_scenarios'=>$added,'retained'=>$retained,'published'=>0);});}
    public static function save_scenario($v){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator required.',403);if(!is_array($v)||array_diff(array_keys($v),array('source_hash','scenario_key','body_html','evidence','rights_basis','expected_revision'))||!preg_match('/^[a-f0-9]{64}$/D',$v['source_hash']??'')||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$v['scenario_key']??'')||!is_string($v['body_html']??null)||strlen($v['body_html'])>500000||CAFCC_Bank_DB::private_reference($v['body_html'])||empty($v['rights_basis'])||strlen(wp_json_encode($v['evidence']??array()))>30000)return CAFCC_Repository::error('Supply authorised common facts with exact source identity and evidence.');
        return CAFCC_Academic::transaction(function()use($v){global $wpdb;$t=CAFCC_Study::table('scenarios');$old=self::scenario($v['source_hash'],$v['scenario_key']);if($old&&(string)$old['revision']!==(string)($v['expected_revision']??''))return CAFCC_Repository::error('Common scenario changed. Reload its revision.',409);$row=array('source_hash'=>$v['source_hash'],'scenario_key'=>$v['scenario_key'],'body_html'=>CAFCC_Practice::html($v['body_html']),'evidence_json'=>wp_json_encode(array('evidence'=>$v['evidence']??array(),'rights_basis'=>sanitize_textarea_field($v['rights_basis']))),'revision'=>$old?(int)$old['revision']+1:1,'updated_at'=>current_time('mysql',true));if(false===($old?$wpdb->update($t,$row,array('id'=>$old['id'])):$wpdb->insert($t,$row)))return CAFCC_Repository::error('Cannot retain common facts.',500);$id=$old?$old['id']:$wpdb->insert_id;
            if($old){$rt=CAFCC_Studio::table();$ids=$wpdb->get_col($wpdb->prepare("SELECT id FROM $rt WHERE source_hash=%s AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.practice_structure.scenario_key'))=%s",$v['source_hash'],$v['scenario_key']));foreach($ids as $rid){$r=CAFCC_Studio::get($rid);$wpdb->update($rt,array('publication_status'=>'draft','status'=>'needs_review','revision'=>(int)$r['revision']+1,'approvals'=>'{}'),array('id'=>$rid));if(!CAFCC_Studio::audit(CAFCC_Studio::get($rid),'common_facts_changed'))return CAFCC_Repository::error('Cannot retain scenario withdrawal audit.',500);}}
            if(!CAFCC_Bank_DB::audit_master('common_scenario',$id,$old,$row))return CAFCC_Repository::error('Cannot retain scenario history.',500);return array_merge($row,array('id'=>$id));
        });
    }
    public static function guard(){ $l=CAFCC_Study::table('links');$s=CAFCC_Study::table('scenarios');return " AND NOT EXISTS(SELECT 1 FROM $l sl LEFT JOIN $s ss ON ss.id=sl.scenario_id WHERE sl.question_id=q.id AND sl.scenario_id>0 AND (ss.id IS NULL OR sl.scenario_revision<>ss.revision))"; }
    public static function common_html($qid){global $wpdb;$l=CAFCC_Study::table('links');$s=CAFCC_Study::table('scenarios');$body=$wpdb->get_var($wpdb->prepare("SELECT s.body_html FROM $l l JOIN $s s ON s.id=l.scenario_id AND s.revision=l.scenario_revision WHERE l.question_id=%d LIMIT 1",$qid));return $body?'<h3>Common facts</h3>'.CAFCC_Practice::html($body).'<h3>Specific requirement</h3>':'';}
    public static function link($row){$d=$row['data'];$v=$d['practice_structure']??array();if(!$v)return true;$scenario=!empty($v['scenario_key'])?self::scenario($d['source_hash'],$v['scenario_key']):null;if(!empty($v['scenario_key'])&&!$scenario)return CAFCC_Repository::error('Import and review the common facts first.');global $wpdb;$existing=$wpdb->get_col($wpdb->prepare('SELECT scenario_id FROM '.CAFCC_Study::table('links').' WHERE question_id=%d AND occurrence_id<>%d',$row['question_id'],$row['occurrence_id']));foreach($existing as $other)if((int)$other!==($scenario?(int)$scenario['id']:0))return CAFCC_Repository::error('Different common facts require a separate stable practice question; existing identities were retained.',409);return false!==$wpdb->replace(CAFCC_Study::table('links'),array('question_id'=>$row['question_id'],'occurrence_id'=>$row['occurrence_id'],'parent_stable_id'=>$v['parent_stable_id']??'','scenario_id'=>$scenario?(int)$scenario['id']:0,'scenario_revision'=>$scenario?(int)$scenario['revision']:0,'alternative'=>$v['alternative']??''))?true:CAFCC_Repository::error('Cannot save question structure.',500);}
    public static function blockers($r){$d=$r['data'];$v=$d['practice_structure']??array();$errors=array();if(self::pilot($d)&&in_array($d['source_type'],array('rtp','mtp','exam'),true)){foreach(array('question'=>$d['official_url']??'','answer'=>$d['answer']['official_url']??'') as $kind=>$url)if(!preg_match('/\.pdf$/i',parse_url($url,PHP_URL_PATH)??''))$errors[]=ucfirst($kind).' official PDF — enter the verified original PDF URL, not an archive/landing page.';}if(!empty($v['scenario_key'])&&!self::scenario($d['source_hash'],$v['scenario_key']))$errors[]='Shared facts — import the exact common scenario before publication.';if(($v['alternative']??'')!==($d['answer']['alternative']??''))$errors[]='Either/Or identity — match the exact alternative in the answer mapping.';
        if(!empty($v['quality_required'])||self::pilot($d)){if(!self::comparison_valid($d))$errors[]='Source comparison — an authorised reviewer must compare this exact reconstruction; imported checks cannot approve it.';$c=$d['quality_checks']??array();$scenario=!empty($v['scenario_key'])?self::scenario($d['source_hash'],$v['scenario_key']):null;if($scenario&&($c['scenario_hash']??'')!==hash('sha256',$scenario['body_html']))$errors[]='Common facts — changed or not compared with the PDF.';foreach(array('question','answer') as $kind){$hash=hash('sha256',$d['rich_content'][$kind]['body_html']??'');if(($c[$kind.'_hash']??'')!==$hash)$errors[]=ucfirst($kind).' comparison — changed or not independently checked against the PDF.';}foreach(array('boundary','tables','figures','shared_facts','answer_complete') as $k)if(empty($c[$k]))$errors[]=ucwords(str_replace('_',' ',$k)).' — confirm source comparison or correct it first.';}
        return $errors;
    }
    public static function comparison_signature($d){$quality=$d['quality_checks']??array();unset($quality['signature']);return hash_hmac('sha256',wp_json_encode(array($d['stable_id']??'', $d['source_hash']??'', $d['official_url']??'', $d['source_type']??'', $d['exam_attempt']??'', $d['mtp_series']??'', $d['edition_id']??null, $d['reference']??'', $d['subreference']??'', $d['question_coordinates']??array(), $d['practice_structure']??array(), $d['answer']??array(), hash('sha256',$d['rich_content']['question']['body_html']??''), hash('sha256',$d['rich_content']['answer']['body_html']??''),hash('sha256',wp_json_encode($d['rich_content']['question']['structure']??array())),hash('sha256',wp_json_encode($d['rich_content']['answer']['structure']??array())),$quality)),wp_salt('auth'));}
    public static function comparison_valid($d){$c=$d['quality_checks']??array();if(empty($c['signature'])||!is_string($c['signature'])||!hash_equals(self::comparison_signature($d),$c['signature']))return false;foreach(array('boundary','tables','figures','shared_facts','answer_complete') as $k)if(empty($c[$k]))return false;foreach(array('question','answer') as $k)if(($c[$k.'_hash']??'')!==hash('sha256',$d['rich_content'][$k]['body_html']??''))return false;$key=$d['practice_structure']['scenario_key']??'';if($key){$s=self::scenario($d['source_hash'],$key);if(!$s||($c['scenario_hash']??'')!==hash('sha256',$s['body_html']))return false;}return true;}
    public static function checklist($r){
        $d=$r['data'];$answer=$d['answer'];$answer_ok=!CAFCC_Studio::stage_valid($r,'answer_mapping');foreach(array('subject_code','source_type','exam_attempt','mtp_series') as $key)if(($answer[$key]??null)!==($d[$key]??''))$answer_ok=false;
        $comparison=self::comparison_valid($d);$checks=array(
            'Official source link'=>array(!empty($d['official_url']),'official_url'),
            'Historical edition'=>array(!CAFCC_Studio::stage_valid($r,'source'),'edition_id'),
            'Question boundary / number'=>array(!CAFCC_Studio::stage_valid($r,'boundary'),'question_coordinates'),
            'Academic tags'=>array(!CAFCC_Studio::stage_valid($r,'classification'),'classification'),
            'Exact answer mapping'=>array($answer_ok,'answer'),
            'Full question text'=>array(!empty($d['rich_content']['question']['body_html']),'rich_question'),
            'Full answer / workings'=>array(!empty($d['rich_content']['answer']['body_html']),'rich_answer'),
            'PDF comparison: tables, figures and common facts'=>array($comparison,'quality_checks'),
            'Publication permission'=>array($d['rights_mode']==='original'||(bool)CAFCC_Rights::resolve($d),'rights_grant_id'),
            'Blocking exceptions'=>array(empty($d['blocking_exceptions']),'blocking_exceptions'));
        $items=array();foreach($checks as $label=>$x)$items[]=array('label'=>$label,'status'=>$x[0]?($x[1]==='quality_checks'?'Confirmed':'Available / checked'):'Needs review or correction','field'=>$x[1]);return $items;
    }
    public static function reviewed_data($d){
        // Called only following an explicit administrator review confirmation.
        $d['blocking_exceptions']=array_values(array_filter($d['blocking_exceptions']??array(),function($code){return $code!=='owner_visual_comparison_required';}));
        $d['quality_checks']=array_fill_keys(array('boundary','tables','figures','shared_facts','answer_complete'),true);
        foreach(array('question','answer') as $kind)$d['quality_checks'][$kind.'_hash']=hash('sha256',$d['rich_content'][$kind]['body_html']??'');
        if(!empty($d['practice_structure']['scenario_key'])){$scene=self::scenario($d['source_hash'],$d['practice_structure']['scenario_key']);if($scene)$d['quality_checks']['scenario_hash']=hash('sha256',$scene['body_html']);}
        $d['quality_checks']['reviewer']=get_current_user_id();$d['quality_checks']['reviewed_at']=current_time('mysql',true);$d['quality_checks']['signature']=self::comparison_signature($d);return $d;
    }
    public static function quality($id,$input){if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator required.',403);$r=CAFCC_Studio::get($id);if(!$r)return CAFCC_Repository::error('Review not found.',404);if(true!==($input['confirmed']??false))return CAFCC_Repository::error('Confirm your comparison of the exact source boundaries, figures, common facts and complete answer.');return CAFCC_Studio::save($id,array('expected_revision'=>$input['expected_revision']??null,'data'=>self::reviewed_data($r['data'])));}
    public static function reconstruction($id,$input){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_array($input)||array_diff(array_keys($input),array('expected_revision','record','confirmed'))||true!==($input['confirmed']??false))return CAFCC_Repository::error('Compare the previous and proposed transcription before confirming.');$r=CAFCC_Studio::get($id);if(!$r)return CAFCC_Repository::error('Review not found.',404);$new=CAFCC_Studio::clean($input['record']??null);if(is_wp_error($new))return $new;$d=$r['data'];foreach(array('stable_id','source_hash','source_key','section','reference','subreference','subject_code','source_type','exam_attempt','mtp_series') as $k)if(($new[$k]??'')!==($d[$k]??''))return CAFCC_Repository::error('Reconstruction identity differs: '.$k.'. Reconcile a split/new source separately; no existing identity was reassigned.',409);
        foreach(array('rich_content','question_page','question_coordinates','heading_evidence','answer','practice_structure','source_provenance','engine_revision','extraction_status','ai_proposal') as $k)$d[$k]=$new[$k]??array();$d['quality_checks']=array();$d['blocking_exceptions']=array_values(array_unique(array_merge($d['blocking_exceptions']??array(),$new['blocking_exceptions']??array())));$saved=CAFCC_Studio::save($id,array('expected_revision'=>$input['expected_revision']??null,'data'=>$d));if(!is_wp_error($saved)&&!CAFCC_Studio::audit($saved,'owner_reconstruction_review'))return CAFCC_Repository::error('Cannot retain reconstruction history.',500);return $saved;
    }
    public static function bulk_create($input){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator required.',403);if(!is_array($input)||array_diff(array_keys($input),array('ids','filters','action'))||!in_array($input['action']??'',array('publish','needs_review','reject'),true))return CAFCC_Repository::error('Choose a bulk owner action.');global $wpdb;$t=CAFCC_Studio::table();$args=array();$where='1=1';
        if(isset($input['ids'])){$ids=$input['ids'];if(!is_array($ids)||!$ids||count($ids)>10000)return CAFCC_Repository::error('Select between 1 and 10,000 rows.');foreach($ids as $id)if(is_wp_error(CAFCC_Repository::id($id)))return CAFCC_Repository::error('Invalid selection.');$where='id IN ('.implode(',',array_fill(0,count($ids),'%d')).')';$args=$ids;}
        else{$f=$input['filters']??array();if(!is_array($f)||array_diff(array_keys($f),array('status','subject','search','source_type','exam_attempt','mtp_series')))return CAFCC_Repository::error('Invalid bulk filter.');foreach($f as $k=>$value){if(!is_string($value)||strlen($value)>120)return CAFCC_Repository::error('Invalid bulk filter value.');if(!$value)continue;if($k==='search'){$where.=' AND (stable_id LIKE %s OR question_number LIKE %s OR exam_attempt LIKE %s OR payload LIKE %s)';$like='%'.$wpdb->esc_like($value).'%';array_push($args,$like,$like,$like,$like);}else{$col=$k==='subject'?'subject_code':$k;$where.=" AND $col=%s";$args[]=$value;}}}
        $sql="SELECT id,revision FROM $t WHERE $where ORDER BY id LIMIT 10001";$rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql,ARRAY_A);if(!$rows||count($rows)>10000)return CAFCC_Repository::error('Selection is empty or exceeds 10,000 records. Narrow the filter.');$key=wp_generate_password(40,false,false);$v=array('owner_id'=>get_current_user_id(),'job_key'=>$key,'action'=>$input['action'],'phase'=>'preview','cursor_position'=>0,'selection_json'=>wp_json_encode($rows),'results_json'=>'[]','modified_at'=>current_time('mysql',true));if(false===$wpdb->insert(CAFCC_Study::table('bulk'),$v))return CAFCC_Repository::error('Cannot retain bulk preview.',500);return array('job_key'=>$key,'selected'=>count($rows),'phase'=>'preview','cursor'=>0);
    }
    public static function bulk_step($key,$input){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator required.',403);if(!is_string($key)||!preg_match('/^[A-Za-z0-9]{40}$/D',$key)||!is_array($input)||array_diff(array_keys($input),array('cursor','apply','confirmed')))return CAFCC_Repository::error('Invalid bulk request.');
        return CAFCC_Academic::transaction(function()use($key,$input){global $wpdb;$t=CAFCC_Study::table('bulk');$job=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE job_key=%s AND owner_id=%d FOR UPDATE",$key,get_current_user_id()),ARRAY_A);if(!$job)return CAFCC_Repository::error('Private owner job not found.',404);$selected=json_decode($job['selection_json'],true);$results=json_decode($job['results_json'],true);$cursor=(int)$job['cursor_position'];if(($input['cursor']??-1)!==$cursor)return CAFCC_Repository::error('Bulk cursor changed. Reload the saved job.',409);$apply=true===($input['apply']??false);
            if($apply&&$job['phase']==='ready'){if(true!==($input['confirmed']??false))return CAFCC_Repository::error('Confirm that you personally approve the valid saved revisions.');$job['phase']='apply';$cursor=0;$results=array_map(function($r){$r['applied']=false;return $r;},$results);}
            elseif($apply&&$job['phase']!=='apply')return CAFCC_Repository::error('Finish the validation preview before applying owner decisions.');
            if($job['phase']==='done'||$job['phase']==='ready')return self::bulk_view($job,$selected,$results);
            if($job['phase']==='apply'&&!$apply)return CAFCC_Repository::error('Continue the confirmed application phase.');
            for($i=$cursor;$i<min(count($selected),$cursor+10);$i++){$ref=$selected[$i];$r=CAFCC_Studio::get($ref['id']);$candidate=$r;if($candidate&&$job['action']==='publish')$candidate['data']=self::reviewed_data($candidate['data']);$errors=!$r?array('Record missing.'):(($r['revision']!=$ref['revision'])?array('Stale revision; owner correction retained.'):($job['action']==='publish'?CAFCC_Release_V5::blockers($candidate):array()));if($job['phase']==='preview')$results[$i]=array('id'=>(int)$ref['id'],'stable_id'=>$r['stable_id']??'','revision'=>(int)$ref['revision'],'blockers'=>$errors,'valid'=>!$errors);
                else{if(!$results[$i]['valid'])continue;if(!$errors){$res=CAFCC_Release_V5::decision($ref['id'],array('expected_revision'=>$ref['revision'],'action'=>$job['action'],'confirmed'=>true,'source_compared'=>$job['action']==='publish'));if(is_wp_error($res))$errors=array($res->get_error_message());}$results[$i]['applied']=!$errors;$results[$i]['apply_errors']=$errors;}}
            $cursor=min(count($selected),$cursor+10);$job['phase']=$cursor===count($selected)?($job['phase']==='preview'?'ready':'done'):$job['phase'];$job['cursor_position']=$cursor;$job['results_json']=wp_json_encode($results);if(false===$wpdb->update($t,array('phase'=>$job['phase'],'cursor_position'=>$cursor,'results_json'=>$job['results_json'],'modified_at'=>current_time('mysql',true)),array('id'=>$job['id'])))return CAFCC_Repository::error('Cannot checkpoint owner batch.',500);return self::bulk_view($job,$selected,$results);
        });
    }
    private static function bulk_view($j,$s,$r){return array('job_key'=>$j['job_key'],'phase'=>$j['phase'],'cursor'=>(int)$j['cursor_position'],'selected'=>count($s),'valid'=>count(array_filter($r,function($v){return $v['valid'];})),'blocked'=>count(array_filter($r,function($v){return !$v['valid'];})),'applied'=>count(array_filter($r,function($v){return !empty($v['applied']);})),'issue_count'=>count(array_filter($r,function($v){return !$v['valid']||!empty($v['apply_errors']);})),'issues'=>array_slice(array_values(array_filter($r,function($v){return !$v['valid']||!empty($v['apply_errors']);})),0,100));}
    public static function init(){
        add_action('rest_api_init',function(){foreach(array('preview','apply') as $action)register_rest_route('cafcc/v6','/admin/scenarios-batch/'.$action,array('methods'=>'POST','permission_callback'=>function($r){return CAFCC_REST::permission($r,true);},'callback'=>function($r)use($action){$v=CAFCC_Studio::body($r);return is_wp_error($v)?$v:self::scenario_batch($action,$v);}));});
        add_action('rest_api_init',function(){register_rest_route('cafcc/v6','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/reconstruction',array('methods'=>'POST','permission_callback'=>function($r){return CAFCC_REST::permission($r,true);},'callback'=>function($r){$v=CAFCC_Studio::body($r);return is_wp_error($v)?$v:self::reconstruction((int)$r['id'],$v);}));});
        add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r,true);};register_rest_route('cafcc/v6','/admin/scenarios',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r){$v=CAFCC_Studio::body($r);return is_wp_error($v)?$v:self::save_scenario($v);}));register_rest_route('cafcc/v6','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/compare',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r){return self::quality((int)$r['id'],$r->get_json_params()??array());}));register_rest_route('cafcc/v6','/admin/bulk-review',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r){return self::bulk_create($r->get_json_params()??array());}));register_rest_route('cafcc/v6','/admin/bulk-review/(?P<key>[A-Za-z0-9]{40})',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){global $wpdb;$t=CAFCC_Study::table('bulk');$j=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE owner_id=%d AND job_key=%s",get_current_user_id(),$r['key']),ARRAY_A);return $j?self::bulk_view($j,json_decode($j['selection_json'],true),json_decode($j['results_json'],true)):CAFCC_Repository::error('Owner batch not found.',404);}));register_rest_route('cafcc/v6','/admin/bulk-review/(?P<key>[A-Za-z0-9]{40})',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r){return self::bulk_step($r['key'],$r->get_json_params()??array());}));});
        add_action('admin_enqueue_scripts',function(){if(($_GET['page']??'')==='cafcc-studio'&&CAFCC_Repository::admin_allowed()){wp_enqueue_script('cafcc-review-tools',plugins_url('assets/review-tools.js',CAFCC_FILE),array('cafcc-studio'),CAFCC_VERSION,true);wp_enqueue_style('cafcc-review-tools',plugins_url('assets/study.css',CAFCC_FILE),array(),CAFCC_VERSION);wp_localize_script('cafcc-review-tools','CAFCCReviewTools',array('url'=>rest_url('cafcc/v6/admin/'),'nonce'=>wp_create_nonce('wp_rest')));}});
